using System.IO;
using System.Text;
using System.Threading;
using System.Xml.Linq;
namespace Fluent.Pdf.Formats;
/// <summary>Closed, passive XSL-FO block/table layout and finite declarative XML transformation. No general XSLT evaluator or external resolver executes.</summary>
public static class PdfFormattingObjects
{
    private static readonly XNamespace Fo="http://www.w3.org/1999/XSL/Format", Xsl="http://www.w3.org/1999/XSL/Transform";
    /// <summary>Reads one simple page master/sequence/body with text blocks and explicit tables. Fonts and shaping are caller supplied; unsupported formatting always rejects.</summary>
    public static PdfDocument Import(Stream source, PdfFlowTextStyle body, PdfProviderRegistry providers, int maximumPages = 1000, PdfOperationPolicy? policy = null, CancellationToken cancellationToken = default)
        => Run(source,null,body,providers,maximumPages,policy,cancellationToken);
    /// <summary>Applies a closed XSLT1.0 data profile: one root template, literal FO, text, value-of and for-each over finite literal child paths. Includes/imports/functions/recursion/scripts/URI access and unknown formatting reject before layout.</summary>
    public static PdfDocument Transform(Stream xml, Stream stylesheet, PdfFlowTextStyle body, PdfProviderRegistry providers, int maximumPages = 1000, PdfOperationPolicy? policy = null, CancellationToken cancellationToken = default)
    { if(stylesheet==null || !stylesheet.CanRead) throw new ArgumentException("A readable borrowed stylesheet is required.",nameof(stylesheet));return Run(xml,stylesheet,body,providers,maximumPages,policy,cancellationToken); }
    private static PdfDocument Run(Stream input,Stream? stylesheet,PdfFlowTextStyle body,PdfProviderRegistry providers,int maximumPages,PdfOperationPolicy? policy,CancellationToken token)
    {
        if(input==null || !input.CanRead) throw new ArgumentException("Readable borrowed XML input is required.",nameof(input));if(body==null || providers==null) throw new ArgumentNullException(nameof(body));if(maximumPages<1 || maximumPages>10000) throw new ArgumentOutOfRangeException(nameof(maximumPages));PdfDocument? result=null;var finish=new List<Action<PdfOperationReport>>();try{var report=PdfFont.Run("ImportFormattingObjects","managed.fo-data",policy,token,c=>{var xml=FormatIo.Xml(input,c);if(stylesheet!=null) xml=Apply(xml,FormatIo.Xml(stylesheet,c),c);result=Layout(xml,body,providers,maximumPages,c,finish);},PdfCapability.WriteDocument);foreach(var complete in finish)complete(report);result!.SetCompositionReport(report);return result;}catch{result?.Dispose();throw;}
    }
    private static PdfDocument Layout(XDocument xml,PdfFlowTextStyle body,PdfProviderRegistry providers,int max,PdfOperationContext c,List<Action<PdfOperationReport>> finish)
    {
        var root=xml.Root;Check(root,Fo+"root",Array.Empty<string>(),new[]{Fo+"layout-master-set",Fo+"page-sequence"},c);var masters=One(root!,Fo+"layout-master-set",c);Check(masters,Fo+"layout-master-set",Array.Empty<string>(),new[]{Fo+"simple-page-master"},c);var master=One(masters,Fo+"simple-page-master",c);Check(master,Fo+"simple-page-master",new[]{"master-name","page-width","page-height","margin"},new[]{Fo+"region-body"},c);string name=Required(master,"master-name",c);double width=Length(Required(master,"page-width",c),c),height=Length(Required(master,"page-height",c),c),margin=master.Attribute("margin")==null?0:Length(master.Attribute("margin")!.Value,c,true);if(width<=margin*2 || height<=margin*2)throw Error(c,"Geometry","Page margins require a positive body frame.");var region=One(master,Fo+"region-body",c);Check(region,Fo+"region-body",Array.Empty<string>(),Array.Empty<XName>(),c);var sequence=One(root!,Fo+"page-sequence",c);Check(sequence,Fo+"page-sequence",new[]{"master-reference"},new[]{Fo+"flow"},c);if(Required(sequence,"master-reference",c)!=name)throw Error(c,"MasterReference","An exact local page master is required.");var flow=One(sequence,Fo+"flow",c);Check(flow,Fo+"flow",new[]{"flow-name"},new[]{Fo+"block",Fo+"table"},c);if(Required(flow,"flow-name",c)!="xsl-region-body")throw Error(c,"RegionUnsupported","Only the explicit body flow is supported.");
        var blocks=new List<PdfFlowBlock>();foreach(var element in flow.Elements()){c.Checkpoint();c.Consume(PdfResourceKind.Objects,1);if(element.Name==Fo+"block")blocks.Add(Block(element,body,c));else blocks.Add(Table(element,body,c));}if(blocks.Count==0)throw Error(c,"EmptyFlow","A nonempty body flow is required.");var options=new PdfFormatTextOptions(body,new(new(new(new(0,0,width,height))),PdfMargins.Uniform(margin),maximumPages:max));return FormatText.Build(blocks,options,providers,c,finish);
    }
    private static PdfFlowParagraph Block(XElement element,PdfFlowTextStyle body,PdfOperationContext c)
    {
        Check(element,Fo+"block",new[]{"font-size","space-before","space-after"},Array.Empty<XName>(),c,true);c.Consume(PdfResourceKind.ExpandedBytes,element.Value.Length*6L+1024);var text=new StringBuilder();bool white=false;foreach(char ch in element.Value){c.Checkpoint();if(ch==' '||ch=='\t'||ch=='\r'||ch=='\n'){white=true;continue;}if(white&&text.Length>0)text.Append(' ');white=false;text.Append(ch);}var style=element.Attribute("font-size")==null?body:new PdfFlowTextStyle(body.Fonts,Length(element.Attribute("font-size")!.Value,c),body.TextOptions,body.Color,body.BaselineShift);double before=element.Attribute("space-before")==null?0:Length(element.Attribute("space-before")!.Value,c,true),after=element.Attribute("space-after")==null?0:Length(element.Attribute("space-after")!.Value,c,true);return new(text.ToString(),style,new(spaceBefore:before,spaceAfter:after));
    }
    private static PdfTable Table(XElement table,PdfFlowTextStyle body,PdfOperationContext c)
    {
        Check(table,Fo+"table",new[]{"table-layout"},new[]{Fo+"table-column",Fo+"table-header",Fo+"table-body"},c);if(table.Attribute("table-layout")!=null&&table.Attribute("table-layout")!.Value!="fixed")throw Error(c,"TableUnsupported","Only explicit fixed table layout is supported.");var columns=new List<PdfTableColumn>();foreach(var col in table.Elements(Fo+"table-column")){Check(col,Fo+"table-column",new[]{"column-width"},Array.Empty<XName>(),c);c.Consume(PdfResourceKind.Objects,1);if(columns.Count==1024)throw Error(c,"TableExtent","At most1024 explicit columns are supported.");columns.Add(PdfTableColumn.Fixed(Length(Required(col,"column-width",c),c)));}if(columns.Count==0)throw Error(c,"TableUnsupported","Explicit fixed-width columns are required.");var rows=new List<PdfTableRow>();int headers=0;foreach(var group in table.Elements().Where(e=>e.Name!=Fo+"table-column")){Check(group,group.Name,Array.Empty<string>(),new[]{Fo+"table-row"},c);if(group.Name==Fo+"table-header"&&rows.Count!=0)throw Error(c,"TableUnsupported","The single header must precede body rows.");foreach(var row in group.Elements()){Check(row,Fo+"table-row",Array.Empty<string>(),new[]{Fo+"table-cell"},c);c.Consume(PdfResourceKind.Objects,1);var cells=new List<PdfTableCell>();foreach(var cell in row.Elements()){Check(cell,Fo+"table-cell",Array.Empty<string>(),new[]{Fo+"block"},c);var block=One(cell,Fo+"block",c);cells.Add(new PdfTableCell(new[]{Block(block,body,c)}));}rows.Add(new(cells));if(rows.Count>100000)throw Error(c,"TableExtent","At most100000 rows are supported.");if(group.Name==Fo+"table-header")headers++;}}if(table.Elements(Fo+"table-body").Count()!=1||table.Elements(Fo+"table-header").Count()>1)throw Error(c,"TableUnsupported","Exactly one body and at most one header are required.");return PdfTable.CreateCore(columns.ToArray(),rows,headers,true,100000,c);
    }
    private static XDocument Apply(XDocument source,XDocument sheet,PdfOperationContext c)
    {
        var root=sheet.Root;Check(root,Xsl+"stylesheet",new[]{"version"},new[]{Xsl+"template"},c);if(Required(root!,"version",c)!="1.0")throw Error(c,"StylesheetUnsupported","The closed transform profile uses version1.0.");var template=One(root!,Xsl+"template",c);Check(template,Xsl+"template",new[]{"match"},new[]{Fo+"root"},c);if(Required(template,"match",c)!="/")throw Error(c,"StylesheetUnsupported","One root template is required.");var literal=One(template,Fo+"root",c);Validate(literal,0);c.Consume(PdfResourceKind.Objects,1);c.Consume(PdfResourceKind.ExpandedBytes,256);var result=new XDocument();Emit(literal,source,result,0);return result;
        void Validate(XElement element,int depth){c.Checkpoint();if(depth>128)throw Error(c,"StylesheetDepth","The declarative transform depth exceeds128.");if(element.Name.Namespace==Fo){string[] allowed=element.Name.LocalName switch { "root" or "layout-master-set" or "region-body" or "table-header" or "table-body" or "table-row" or "table-cell"=>Array.Empty<string>(), "simple-page-master"=>new[]{"master-name","page-width","page-height","margin"},"page-sequence"=>new[]{"master-reference"},"flow"=>new[]{"flow-name"},"block"=>new[]{"font-size","space-before","space-after"},"table"=>new[]{"table-layout"},"table-column"=>new[]{"column-width"},_=>throw Error(c,"FormattingUnsupported","Unknown formatting elements reject even in an unselected transform branch.")};if(element.Attributes().Any(a=>!a.IsNamespaceDeclaration&&!allowed.Contains(a.Name.ToString())))throw Error(c,"FormattingUnsupported","Unknown formatting properties reject even in an unselected transform branch.");foreach(var a in element.Attributes())if(!a.IsNamespaceDeclaration&&(a.Name.NamespaceName.Length!=0||a.Value.IndexOfAny(new[]{'{','}'})>=0))throw Error(c,"StylesheetUnsupported","Dynamic attributes are not supported.");}else if(element.Name==Xsl+"for-each"||element.Name==Xsl+"value-of"){Check(element,element.Name,new[]{"select"},element.Name==Xsl+"value-of"?Array.Empty<XName>():element.Elements().Select(e=>e.Name).Distinct().ToArray(),c,false);ValidatePath(Required(element,"select",c));}else if(element.Name==Xsl+"text")Check(element,element.Name,Array.Empty<string>(),Array.Empty<XName>(),c,true);else throw Error(c,"StylesheetUnsupported","Includes, scripts, recursion, functions and unknown transform instructions are rejected.");foreach(var child in element.Elements())Validate(child,depth+1);}
        void Emit(XElement element,XContainer current,XContainer target,int depth){using var scope=c.EnterScope(PdfResourceKind.Depth);c.Checkpoint();if(depth>128)throw Error(c,"StylesheetDepth","The declarative transform depth exceeds128.");if(element.Name==Xsl+"for-each"){foreach(var match in Select(current,Required(element,"select",c)))foreach(var child in element.Elements())Emit(child,match,target,depth+1);return;}if(element.Name==Xsl+"value-of"){var match=Select(current,Required(element,"select",c)).FirstOrDefault();Text(match?.Value??"",target);return;}if(element.Name==Xsl+"text"){Text(element.Value,target);return;}c.Consume(PdfResourceKind.Objects,1+element.Attributes().Count());c.Consume(PdfResourceKind.ExpandedBytes,512+element.Attributes().Sum(a=>a.Value.Length*4L+128));var clone=new XElement(element.Name);foreach(var a in element.Attributes())if(!a.IsNamespaceDeclaration)clone.Add(new XAttribute(a));target.Add(clone);foreach(var node in element.Nodes()){if(node is XElement child)Emit(child,current,clone,depth+1);else if(node is XText text&&!string.IsNullOrWhiteSpace(text.Value))Text(text.Value,clone);}}
        void Text(string value,XContainer target){c.Consume(PdfResourceKind.Objects,1);c.Consume(PdfResourceKind.ExpandedBytes,value.Length*4L+256);target.Add(new XText(value));}
        IEnumerable<XElement> Select(XContainer current,string path){ValidatePath(path);if(path=="."){if(current is XElement element)yield return element;yield break;}IEnumerable<XContainer> nodes=new[]{path[0]=='/'?source:current};foreach(string part in path.TrimStart('/').Split('/'))nodes=Children(nodes,part);foreach(var node in nodes){c.Checkpoint();yield return (XElement)node;}}
        IEnumerable<XContainer> Children(IEnumerable<XContainer> nodes,string name){foreach(var node in nodes)foreach(var child in node.Elements(name)){c.Checkpoint();c.Consume(PdfResourceKind.Objects,1);yield return child;}}
        void ValidatePath(string path){c.Checkpoint();c.Consume(PdfResourceKind.ExpandedBytes,path.Length*8L+1024);if(path==".")return;if(path.Length>512)throw Error(c,"StylesheetPath","A finite literal child path is required.");var parts=path.TrimStart('/').Split('/');if(path.StartsWith("//",StringComparison.Ordinal)||parts.Length>32||parts.Any(v=>v.Length==0||!(v[0]>='A'&&v[0]<='Z'||v[0]>='a'&&v[0]<='z'||v[0]=='_')||v.Any(ch=>!(ch>='A'&&ch<='Z'||ch>='a'&&ch<='z'||ch>='0'&&ch<='9'||"_.-".IndexOf(ch)>=0))))throw Error(c,"StylesheetPath","Only literal unqualified child names and the current element are supported; XPath functions/operators are not executed.");}
    }
    private static void Check(XElement? e,XName name,string[] attributes,XName[] children,PdfOperationContext c,bool text=false){c.Checkpoint();if(e?.Name!=name||e.Attributes().Any(a=>!a.IsNamespaceDeclaration&&(!attributes.Contains(a.Name.ToString())))||e.Elements().Any(child=>!children.Contains(child.Name))||!text&&e.Nodes().OfType<XText>().Any(t=>!string.IsNullOrWhiteSpace(t.Value)))throw Error(c,"FormattingUnsupported","An unsupported formatting/transform element, property or text was requested.");}
    private static XElement One(XElement parent,XName name,PdfOperationContext c){var elements=parent.Elements(name).Take(2).ToArray();if(elements.Length!=1)throw Error(c,"Structure","An exact single required element is missing or ambiguous.");return elements[0];}
    private static string Required(XElement e,string name,PdfOperationContext c)=>e.Attribute(name)?.Value??throw Error(c,"Structure","An explicit required attribute is missing.");
    private static double Length(string value,PdfOperationContext c,bool zero=false){if(value.Length>128||value.Length<3)throw Error(c,"Length","A bounded explicit physical length is required.");string unit=value.Substring(value.Length-2);double factor=unit=="pt"?1:unit=="mm"?72/25.4:unit=="cm"?72/2.54:unit=="in"?72:0;if(factor==0)throw Error(c,"Length","Only explicit pt/mm/cm/in lengths are supported.");double n=FormatIo.Number(value.Substring(0,value.Length-2),c)*factor;if(n<(zero?0:double.Epsilon)||n>14400)throw Error(c,"Length","Physical lengths must be positive and at most14400 points.");return n;}
    private static PdfException Error(PdfOperationContext c,string code,string message)=>PdfWriterCore.Error(c,"Fo."+code,message);
}
